(2786, 27, 'عبدالرحمن ', '2025-01-26', '2025-01-27', 'طباعة كروت شخصية وجهين مع سلوفان مطفي مقاس 5*9', 80.00, 1000, '2025-01-26 20:12:44', '703', 1, 0, 68, 'جاهز', 'الكرت الاول ملغي يتم اعتماد الكرت المكتوب عليه بعد التعديل '),
(2787, 29, 'سامي', '2025-01-26', NULL, 'طلب عدلها رقم 3\r\nالتفاصيل داخل المسميات تبع الملف وسيتم شرحها لعلي الصباح ', 0.00, 0, '2025-01-26 20:14:59', '704', 1, 0, 56, 'قيد التنفيذ', ''),
(2788, 26, 'محمد شيخ ', '2025-01-26', NULL, 'درع اضافي على طلب رقم 700 ', 0.00, 1, '2025-01-26 20:51:43', '705', 1, 0, 76, 'قيد التنفيذ', ''),
(2789, 28, 'معتز', '2025-01-26', '2025-01-27', 'طباعة عدد 15 استاند طاولة مقاس 18*13 حسب المقاس المناسب لكروت الطاولة طولي\r\nطباعة عدد 50 كرت مقمش عربي مقاس A6\r\nطباعة عدد 50 كرت مقمش انجليزي مقاس A6\r\n', 95.00, 115, '2025-01-26 20:57:37', '706', 1, 0, 63, 'جاهز', ''),
(2790, 17, 'الادمن', '2025-01-27', NULL, 'طباعة ملون A4 على hp \r\nF29   العدد 4 \r\nF30   العدد 14\r\nارسالها للروابي للتجليد ', 1840.00, 18, '2025-01-27 07:34:26', '707', 1, 0, 47, 'جاهز', 'تم تسليم نسختين من الطلب السابق'),
(2791, 25, 'ابراهيم', '2025-01-27', NULL, 'تصميم وطباعة كيس مقاس الطول 33 سم العرض 30 سم الارتفاع 11 سم بدون حبل مع تخريم من أعلى نفس الصورة المرسلة مقاس 8 سم ملاحظة لازم يكون التخريم متطابق من الجهتين مع وجود مسافة بين الشعار والتخريم 11 سم	', 1200.00, 100, '2025-01-27 07:52:04', '708', 1, 0, 74, 'قيد التنفيذ', 'تم اعتماد اخر عينة \r\nمع تعديل  تصغير حجم الشعار \r\n الاهتمام بالقص \r\nالتخريم  من الجهتين يكون متطابق '),
(2792, 27, 'علي محمود', '2025-01-27', NULL, 'طباعة الشعار في الدائرة الصغير في الحبتين المرسلة لكم من قبل اما طباعة وصب ايبوكسي او اكريلك ولاصقة داخل الدائرة \r\nيتم عمل الافضل والمناسب للاستخدام اليومي ', 0.00, 2, '2025-01-27 08:28:11', '709', 1, 0, 62, 'قيد التنفيذ', ''),
(2793, 27, 'علي محمود', '2025-01-27', NULL, 'بروش اكريك سمك 4 ملي او 2 ملي المناسب  + طباعة uv + صب ايبوكسي ', 0.00, 8, '2025-01-27 08:33:54', '710', -1, 0, 62, 'في الانتظار', ''),
(2794, 26, 'محمد عبدالرحمن', '2025-01-27', '2025-01-27', 'كررت داي كت قص كيرف 350جرام سلفان مطفي  وجهين 9*5', 100.00, 1000, '2025-01-27 08:36:31', '711', 1, 0, 61, 'جاهز', ''),
(2795, 28, 'معتز', '2025-01-27', NULL, 'تصميم استاند شفاف مع قاعدة مقاس A5  وكتابة الكلمات المرسلة باليوفي مع وضع قبعة التخرج  وارسال التصميم قبل الطباعة للاعتماد\r\nبحروف من نور واطياف من وداد يسعدني انا عمتك حبيبة ان اهنئك بجهودك المثمرة التي تبعث على الفخر والي الامام ومزيد من النجاح\r\nعمتك.حبيبة', 0.00, 1, '2025-01-27 10:40:08', '712', 1, 0, 63, 'قيد التنفيذ', ''),
(2796, 28, 'معتز', '2025-01-27', '2025-01-27', 'طباعة كتيبات A6 تنطوي تصير مثل كفة اليد صغيرة نسخة من كل كتيب وتدبيس وسطي ( الغلاف 200جرام والمحتوى 150 جرام )\r\nطباعة متر استيكر بلوتر مع القص \r\nطباعة عدد 12 كرت مقاس 9*6\r\nطباعة 31 كرت مقاس 12*8', 50.00, 50, '2025-01-27 11:20:39', '713', 1, 0, 63, 'جاهز', ''),
(2797, 27, 'علي محمود', '2025-01-27', NULL, 'بروش اكريك سمك 4 ملي او 2 ملي المناسب + طباعة uv + صب ايبوكسي  ( مقاس البروش 6.4*3.3 سم ) ', 64.00, 8, '2025-01-27 14:46:41', '714', 1, 0, 62, 'قيد التنفيذ', ''),
(2798, 30, 'ايهاب', '2025-01-27', '2025-01-27', 'طباعه عينه استيكر مقاس مناسب على الاكواب بدون تركيب\r\nاستيكر يوفي و داي كت وبلاستيك الافضل من وجهة نظركم \r\nالاستيكر يكون دائري وداخله الشعار\r\nسوي 5 حبات من كل نوع', 60.00, 15, '2025-01-27 17:14:34', '715', 1, 0, 71, 'جاهز', ''),
(2799, 25, 'بهاء', '2025-01-27', '2025-01-27', 'شعار يوفي 25 * 25 على الظهر وشعار 8*8 صغير ', 25.00, 1, '2025-01-27 17:41:04', '716', 1, 0, 64, 'جاهز', ''),
(2800, 25, 'بهاء', '2025-01-27', NULL, 'شعار يوفي 25 * 25 على الظهر وشعار 8*8 صغير ', 0.00, 1, '2025-01-27 17:43:17', '717', -1, 0, 64, 'في الانتظار', ''),
(2801, 25, 'ابراهيم', '2025-01-27', NULL, 'طباعة مجلة مقاس A5 بالعرض  الورق الخارجي 300 جرام + سلوفان مطفي - الورق الداخلي 200 جرام   تدبيس وسطى \r\nمجلة 10 نسخ \r\nمجلة 5 نسخ ', 0.00, 15, '2025-01-27 20:00:28', '718', 0, 0, 74, 'في الانتظار', 'التسليم غدا  الساعة 6'),
(2802, 26, 'محمد عبدالرحمن', '2025-01-27', NULL, 'الرجاء طباعة عينه من كل ملف وارسالها للتعميد على الطلبية كاملة (ارسلة العينات من قبل مع عبدالمجيد)\r\n', 0.00, 1, '2025-01-27 20:41:25', '719', 0, 0, 61, 'في الانتظار', '');
